{
  "versao": "1-ia-sozinha",
  "anotacoes": [
    {
      "trecho_id": "STATUS_A.RESUMO",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "está prevista para D40",
          "motivo": "valor_divergente",
          "correto_seria": "A Liberação de engenharia está prevista para D42."
        },
        {
          "citacao": "disponibilidade do protótipo para D25",
          "motivo": "valor_divergente",
          "correto_seria": "O protótipo estará disponível em D27."
        },
        {
          "citacao": "O caminho crítico passa pela entrega da GearWorks em D20",
          "motivo": "premissa_alterada",
          "correto_seria": "O caminho crítico passa pela entrega da MetalForm em D22 e segue pela montagem, pelo teste de vida, pela validação, pela documentação e pela liberação."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_A.SUPRIMENTOS",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "com 2 dias de folga",
          "motivo": "valor_divergente",
          "correto_seria": "A MotorTech fica com 4 dias de folga."
        },
        {
          "citacao": "sem folga",
          "motivo": "valor_divergente",
          "correto_seria": "A GearWorks fica com 2 dias de folga."
        },
        {
          "citacao": "em D17",
          "motivo": "valor_divergente",
          "correto_seria": "A MetalForm entrega em D22."
        },
        {
          "citacao": "com 3 dias de folga",
          "motivo": "valor_divergente",
          "correto_seria": "A MetalForm fica com 0 dias de folga."
        },
        {
          "citacao": "com 4 dias de folga",
          "motivo": "valor_divergente",
          "correto_seria": "A SensePro fica com 6 dias de folga."
        },
        {
          "citacao": "com apenas 1 dia de folga",
          "motivo": "valor_divergente",
          "correto_seria": "O fornecedor da placa de controle e do chicote fica com 3 dias de folga."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_A.ENGENHARIA",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "de D20 a D25",
          "motivo": "valor_divergente",
          "correto_seria": "A montagem do protótipo ocorre de D22 a D27."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_A.TESTES",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "Todos os testes começam em D25",
          "motivo": "valor_divergente",
          "correto_seria": "Todos os testes começam em D27."
        },
        {
          "citacao": "carga, 4 dias, até D29",
          "motivo": "valor_divergente",
          "correto_seria": "O teste de carga termina em D31."
        },
        {
          "citacao": "térmico, 6 dias, até D31",
          "motivo": "valor_divergente",
          "correto_seria": "O teste térmico termina em D33."
        },
        {
          "citacao": "vida, 10 dias, até D35",
          "motivo": "valor_divergente",
          "correto_seria": "O teste de vida termina em D37."
        },
        {
          "citacao": "vedação, 3 dias, até D28",
          "motivo": "valor_divergente",
          "correto_seria": "O teste de vedação termina em D30."
        },
        {
          "citacao": "compatibilidade eletromagnética, 5 dias, até D30",
          "motivo": "valor_divergente",
          "correto_seria": "O teste de compatibilidade eletromagnética termina em D32."
        },
        {
          "citacao": "concluída em D35",
          "motivo": "valor_divergente",
          "correto_seria": "A validação é concluída em D37, ao fim do teste de vida."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_A.CUSTOS",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "R$ 152.000,00",
          "motivo": "valor_divergente",
          "correto_seria": "O orçamento total passa a R$ 152.600,00."
        },
        {
          "citacao": "de R$ 12.000,00",
          "motivo": "valor_divergente",
          "correto_seria": "A parcela de gestão e instalação passa a R$ 12.600,00, incluindo os dois dias além de D40."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_A.OBSERVACOES",
      "rotulo": "SEM_AFIRMACAO",
      "informacoes": [],
      "observacao": "As afirmações sobre motivação e comunicação são opiniões; a revisão futura por Ana não é verificável pelo estado fornecido."
    },
    {
      "trecho_id": "STATUS_B.RESUMO",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "está dentro do cronograma",
          "motivo": "premissa_alterada",
          "correto_seria": "O cronograma agora prevê a liberação em D42, dois dias depois da previsão original de D40."
        },
        {
          "citacao": "sem risco no caminho crítico",
          "motivo": "premissa_alterada",
          "correto_seria": "A entrega da MetalForm em D22 atrasa o caminho crítico, que agora passa por esse fornecedor."
        },
        {
          "citacao": "fim da sexta semana",
          "motivo": "valor_divergente",
          "correto_seria": "A liberação está prevista para o início da sétima semana, em D42."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_B.SUPRIMENTOS",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "Todas as entregas de fornecedores estão programadas para a terceira semana.",
          "motivo": "valor_divergente",
          "correto_seria": "A entrega da MetalForm é em D22, na quarta semana; as demais entregas de fornecedores permanecem na terceira semana."
        },
        {
          "citacao": "O fornecedor do redutor é o último a entregar, no fim dessa semana",
          "motivo": "premissa_alterada",
          "correto_seria": "A MetalForm é a última a entregar, em D22, na quarta semana; o redutor chega em D20, no fim da terceira semana."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_B.ENGENHARIA",
      "rotulo": "CORRETO",
      "informacoes": [],
      "observacao": "A montagem ocorre de D22 a D27, ainda ao longo da quarta semana."
    },
    {
      "trecho_id": "STATUS_B.TESTES",
      "rotulo": "CORRETO",
      "informacoes": [],
      "observacao": "Os testes começam em D27, no fim da quarta semana; a validação termina em D37, no início da sexta semana."
    },
    {
      "trecho_id": "STATUS_B.CUSTOS",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "sem desvios em relação ao total aprovado de R$ 152.000,00",
          "motivo": "valor_divergente",
          "correto_seria": "O total passa a R$ 152.600,00, R$ 600,00 acima do total aprovado."
        },
        {
          "citacao": "nem de gestão",
          "motivo": "afirmacao_conflitante",
          "correto_seria": "Há previsão de dois dias extras de gestão, após D40."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_B.OBSERVACOES",
      "rotulo": "SEM_AFIRMACAO",
      "informacoes": [],
      "observacao": "A afirmação sobre o clima da equipe é uma opinião; a informação sobre a bancada do projeto Beta não se refere ao Alfa."
    }
  ]
}
